%%\ Masa y centro de masa de una lamina triangular
% Vertices: (0,0), (1,0), (0,2)   |   Densidad: rho(x,y) = 1 + 3x + y
% Region D: 0 <= x <= 1,  0 <= y <= 2 - 2x
clear; clc; close all;

%%\ 1. Calculo simbolico 
syms x y
rho = 1 + 3*x + y;
ytop = 2 - 2*x;

m  = int(int(rho,   y, 0, ytop), x, 0, 1);   % masa
My = int(int(x*rho, y, 0, ytop), x, 0, 1);   % momento respecto al eje y
Mx = int(int(y*rho, y, 0, ytop), x, 0, 1);   % momento respecto al eje x

xbar = My/m;
ybar = Mx/m;

fprintf('Masa m      = %s = %.4f\n', char(m),  double(m)); %[output:697415da]
fprintf('My          = %s = %.4f\n', char(My), double(My)); %[output:6745f3bb]
fprintf('Mx          = %s = %.4f\n', char(Mx), double(Mx)); %[output:3f329148]
fprintf('x barra     = %s = %.4f\n', char(xbar), double(xbar)); %[output:128242ae]
fprintf('y barra     = %s = %.4f\n', char(ybar), double(ybar)); %[output:81774ea7]

%%\ 2. Verificacion numerica
rho_f  = @(x,y) 1 + 3*x + y;
ymax_f = @(x) 2 - 2*x;

m_n  = integral2(rho_f,                    0, 1, 0, ymax_f);
My_n = integral2(@(x,y) x.*rho_f(x,y),     0, 1, 0, ymax_f);
Mx_n = integral2(@(x,y) y.*rho_f(x,y),     0, 1, 0, ymax_f);
fprintf('\nVerificacion numerica: m = %.4f, (xbar, ybar) = (%.4f, %.4f)\n', ... %[output:group:383bb882] %[output:8a6b265c]
    m_n, My_n/m_n, Mx_n/m_n); %[output:group:383bb882] %[output:8a6b265c]


[U, V] = meshgrid(linspace(0, 1, 80), linspace(0, 1, 80));
X = U;
Y = (2 - 2*U) .* V;
R = rho_f(X, Y);

figure('Color', 'w', 'Position', [100 100 560 620]); hold on; %[output:78eba369]
surf(X, Y, zeros(size(X)), R, 'EdgeColor', 'none');    %[output:78eba369]
view(2);                                             %[output:78eba369]
colormap(parula); %[output:78eba369]
cb = colorbar; cb.Label.String = '\rho(x,y) = 1 + 3x + y'; %[output:78eba369]

% Contorno del triangulo
plot([0 1 0 0], [0 0 2 0], 'k-', 'LineWidth', 2); %[output:78eba369]

% Centro de masa
xc = double(xbar);  yc = double(ybar);
plot(xc, yc, 'rp', 'MarkerSize', 16, 'MarkerFaceColor', 'r', 'MarkerEdgeColor', 'w'); %[output:78eba369]
text(xc + 0.05, yc + 0.08, sprintf('CM = (%.3f, %.3f)', xc, yc), ... %[output:78eba369]
    'Color', 'k', 'FontWeight', 'bold', 'BackgroundColor', 'w', 'Margin', 2); %[output:78eba369]

% Etiquetas de vertices
text(-0.02, -0.08, '(0,0)', 'HorizontalAlignment', 'right'); %[output:78eba369]
text( 1.02, -0.08, '(1,0)', 'HorizontalAlignment', 'left'); %[output:78eba369]
text(-0.02,  2.00, '(0,2)', 'HorizontalAlignment', 'right'); %[output:78eba369]

axis equal; axis([-0.3 1.3 -0.3 2.3]); %[output:78eba369]
xlabel('x'); ylabel('y'); %[output:78eba369]
title('Lamina triangular: densidad y centro de masa'); %[output:78eba369]
box on; %[output:78eba369]

%[output:78eba369]

